def rescale_to_unit(numbers: List[float]) -> List[float]:
    min_val = min(numbers)
    max_val = max(numbers)
    range_val = max_val - min_val  # Ensure range is calculated once
    return [(num - min_val) / range_val for num in numbers] if range_val != 0 else [0.0] * len(numbers)

